class Historial {
  constructor(entradas, indice) {
    this.entradas = entradas.map((url) => ({ url, estado: null }));
    this.i = indice;
    this.avisos = 0;                                  // cuántas veces saltaría popstate
  }
  pushState(estado, url) {
    this.entradas.splice(this.i + 1);                 // lo que había «adelante» se descarta
    this.entradas.push({ url, estado });
    this.i++;
  }
  replaceState(estado, url) { this.entradas[this.i] = { url, estado }; }
  go(n) {
    const j = this.i + n;
    if (j < 0 || j >= this.entradas.length) return;   // no hay a dónde ir: no pasa nada
    this.i = j;
    this.avisos++;                                    // solo moverse dispara popstate
  }
  back() { this.go(-1); }
  forward() { this.go(1); }
  fila(txt) {
    console.log(txt.padEnd(36), 'len=' + this.entradas.length, 'url=' + this.entradas[this.i].url.padEnd(3), 'popstate=' + this.avisos);
  }
}

