const tabla = [
  { patron: '/',            vista: () => '<h1>Inicio</h1>' },
  { patron: '/pedidos/:id', vista: (p) => `<h1>Pedido ${p.id}</h1>` },
  { patron: '/acerca',      vista: () => '<h1>Acerca</h1>' },
].map((r) => {
  const nombres = [];
  const fuente = r.patron.replace(/:([a-z]+)/g, (_, n) => { nombres.push(n); return '([^/]+)'; });
  return { ...r, nombres, re: new RegExp('^' + fuente + '/?$') };
});

function resolver(ruta) {
  for (const r of tabla) {
    const m = r.re.exec(ruta);
    if (m) return { r, params: Object.fromEntries(r.nombres.map((n, i) => [n, decodeURIComponent(m[i + 1])])) };
  }
  return null;
}

function pintar() {
  const hallada = resolver(location.pathname);
  document.getElementById('vista').innerHTML =
    hallada ? hallada.r.vista(hallada.params) : '<h1>404</h1>';
}

function ir(ruta, { reemplazar = false } = {}) {
  history[reemplazar ? 'replaceState' : 'pushState'](null, '', ruta);
  pintar();
}

